-- Disposable local fixture; all writes roll back, no real users or payments.
begin;
set request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
create function pg_temp.test_warmup(p_hsp boolean) returns void language plpgsql as $$
declare org uuid:=gen_random_uuid(); show_id uuid:=gen_random_uuid(); day_id uuid:=gen_random_uuid(); warm uuid:=gen_random_uuid(); directory uuid:=gen_random_uuid();
 owner_id uuid:=gen_random_uuid(); product uuid:=gen_random_uuid(); hsp_product uuid:=gen_random_uuid(); h uuid; request uuid; first_request uuid; ctx uuid; cfg jsonb; preview jsonb; current_version bigint; count_before integer; selected_ids uuid[];
begin
 insert into public.organizations(id,name,slug,currency) values(org,'Warmup DEMO',org::text,'CAD');
 insert into public.organization_members(organization_id,user_id,role) values(org,'20000000-0000-0000-0000-000000000002','admin');
 insert into public.shows(id,organization_id,name,slug,start_date,end_date,default_currency,status,is_public) values(show_id,org,'Warmup DEMO',show_id::text,current_date,current_date,'CAD','open',true);
 select d.id into day_id from public.show_days d where d.organization_id=org order by d.day_date limit 1;
 insert into public.contacts(id,type,first_name,last_name,linked_user_id) values(owner_id,'owner','Owner','DEMO','20000000-0000-0000-0000-000000000004');
 insert into public.organization_disciplines(id,organization_id,discipline_id) select directory,org,id from public.disciplines order by id limit 1;
 insert into public.directory_contacts(organization_discipline_id,contact_id) values(directory,owner_id);
 insert into public.organization_products(id,organization_id,name,category,default_price,tax_applicable) values(product,org,'Warmup DEMO','merch',25,true);
 if p_hsp then insert into public.organization_products(id,organization_id,name,category,default_price,tax_applicable) values(hsp_product,org,'HSP DEMO','merch',5,true);end if;
 insert into public.show_score_paid_warmups(id,organization_id,show_id,show_day_id,name,registration_enabled,entry_fee,capacity) values(warm,org,show_id,day_id,'Warmup DEMO',true,25,2);
 execute 'set local role authenticated';
 execute format('update public.show_score_paid_warmups set name=name,entry_fee=25,capacity=2,entries=''[]'' where id=%L',warm);
 get diagnostics count_before=row_count;
 assert count_before=1,'Authenticated staff form update stays compatible';
 perform public.billing_test_error(format('update public.show_score_paid_warmups set registration_state=''validated'' where id=%L',warm),'permission denied');
 execute 'reset role';
 for i in 1..4 loop
  h:=gen_random_uuid();
  insert into public.horses(id,name,primary_owner_contact_id) values(h,'Horse DEMO '||i,owner_id);
  insert into public.horse_contacts(horse_id,contact_id,role) values(h,owner_id,'owner');
  insert into public.directory_horses(organization_discipline_id,horse_id) values(directory,h);
  perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000004',true);
  request:=public.paid_warmup_request(warm,h);
  assert public.paid_warmup_request(warm,h)=request,'Duplicate request must reuse same horse request';
  if i=1 then first_request:=request;end if;
  perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
 end loop;
 assert (select count(*) from public.paid_warmup_requests where warmup_id=warm)=4;
 assert not has_table_privilege('authenticated','public.paid_warmup_requests','INSERT');
 assert not has_column_privilege('authenticated','public.show_score_paid_warmups','registration_state','UPDATE');
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000004',true);
 perform public.billing_test_error(format('select public.paid_warmup_manage(%L,4,''draw'')',warm),'WARMUP_FORBIDDEN');
 assert jsonb_array_length(public.paid_warmup_signup_options(org))=1;
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000005',true);
 perform public.billing_test_error(format('select public.paid_warmup_roster(%L)',warm),'WARMUP_FORBIDDEN');
 perform public.billing_test_error(format('select public.paid_warmup_request(%L,%L)',warm,h),'WARMUP_FORBIDDEN');
 assert jsonb_array_length(public.paid_warmup_signup_options(org)#>'{0,requests}')=0,'Other owners requests stay private';
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
 perform public.paid_warmup_manage(warm,4,'draw');
 assert (select count(*) from public.paid_warmup_requests where warmup_id=warm and status='selected')=2;
 assert (select count(*) from public.paid_warmup_requests where warmup_id=warm and status='waiting')=2;
 assert (select count(distinct draw_rank) from public.paid_warmup_requests where warmup_id=warm)=4;
 assert (select jsonb_array_length(entries) from public.show_score_paid_warmups where id=warm)=2,'ShowScore roster synchronized';
 assert public.paid_warmup_roster(warm)->>'currency'='CAD';
 select registration_version into current_version from public.show_score_paid_warmups where id=warm;
 perform public.billing_test_error(format('select public.paid_warmup_manage(%L,%s,''draw'')',warm,current_version),'WARMUP_DRAW_ALREADY_DONE');
 perform public.billing_test_error(format('select public.paid_warmup_manage(%L,%s,''promote'')',warm,current_version),'WARMUP_FULL');
 select array_agg(id order by position desc) into selected_ids from public.paid_warmup_requests where warmup_id=warm and status='selected';
 perform public.paid_warmup_manage(warm,current_version,'reorder',null,selected_ids);
 assert not exists(select 1 from public.paid_warmup_requests where warmup_id=warm and billed_at is not null),'No billing during draw/reorder';
 select registration_version into current_version from public.show_score_paid_warmups where id=warm;
 perform public.billing_test_error(format('select public.paid_warmup_manage(%L,%s,''reorder'',null,array[%L::uuid,%L::uuid])',warm,current_version,gen_random_uuid(),selected_ids[1]),'WARMUP_INVALID_ORDER');
 perform public.billing_test_error(format('select public.paid_warmup_billing_preview(%L,%s,%L)',warm,current_version,product),'WARMUP_BILLING_CONTEXT_REQUIRED');
 -- Explicit opt-in fixture, using the existing tax engine with a fictitious 5%% tax.
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
 perform public.billing_set_capabilities(org,null,true,true,true);
 perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
 select value->'config' into cfg from public.billing_test_fixture where key='config';
 ctx:=public.billing_create_context(org,show_id,null,null,'CAD',cfg,now()-interval '1 day',null,jsonb_build_array(jsonb_build_object('product_id',product,'unit_price',25,'taxes',jsonb_build_array(jsonb_build_object('code','TEST','name','DEMO TAX','jurisdiction','DEMO','rate',5)))) || case when p_hsp then jsonb_build_array(jsonb_build_object('product_id',hsp_product,'unit_price',5,'taxes',jsonb_build_array(jsonb_build_object('code','HSPTEST','name','DEMO HSP TAX','jurisdiction','DEMO','rate',5)))) else '[]'::jsonb end);
 if p_hsp then perform public.billing_hsp_adopt(ctx,hsp_product,'{"association":{"name":"DEMO association","address":"DEMO","tax_number_1":"DEMO-ASSOC","demo":true},"hsp":{"name":"DEMO HSP","address":"DEMO","tax_number_1":"DEMO-HSP","demo":true}}','DEMO');end if;
 perform public.billing_set_capabilities(org,ctx,true,true,true,true,2026);
 preview:=public.paid_warmup_billing_preview(warm,current_version,product);
 assert jsonb_array_length(preview->'items')=2;
 assert (select count(*) from public.billing_charges where organization_id=org)=0,'Preview creates no financial charges';
 perform public.billing_test_error(format('select public.paid_warmup_validate(%L,%s,%L,''bad hash'')',warm,current_version,product),'WARMUP_REVIEW_CHANGED');
 perform public.paid_warmup_validate(warm,current_version,product,preview->>'hash');
 assert (select count(*) from public.billing_charges where organization_id=org)=2+case when p_hsp then 1 else 0 end;
 assert (select sum(total) from public.billing_charges where organization_id=org)=case when p_hsp then 57.75 else 52.50 end;
 assert not exists(select 1 from public.paid_warmup_requests where warmup_id=warm and status='waiting' and billed_at is not null);
 select registration_version into current_version from public.show_score_paid_warmups where id=warm;
 preview:=public.paid_warmup_billing_preview(warm,current_version,product);
 perform public.paid_warmup_validate(warm,current_version,product,preview->>'hash');
 assert (select count(*) from public.billing_charges where organization_id=org)=2+case when p_hsp then 1 else 0 end,'Repeat validation creates no duplicate charges';
 select registration_version into current_version from public.show_score_paid_warmups where id=warm;
 perform public.paid_warmup_manage(warm,current_version,'remove',selected_ids[1]);
 assert (select count(*) from public.billing_charges where organization_id=org)=2+case when p_hsp then 1 else 0 end,'Cancellation preserves charges for manual correction';
 assert (select billed_at is not null and status='cancelled' from public.paid_warmup_requests where id=selected_ids[1]);
 select registration_version into current_version from public.show_score_paid_warmups where id=warm;
 perform public.paid_warmup_manage(warm,current_version,'promote');
 select registration_version into current_version from public.show_score_paid_warmups where id=warm;
 preview:=public.paid_warmup_billing_preview(warm,current_version,product);
 assert jsonb_array_length(preview->'items')=1,'Replacement alone awaits billing approval';
 perform public.paid_warmup_validate(warm,current_version,product,preview->>'hash');
 assert (select count(*) from public.billing_charges where organization_id=org)=3+case when p_hsp then 1 else 0 end;
 assert (select count(*) from public.paid_warmup_events where warmup_id=warm)>=8,'Auditable draw, changes and billing';
end $$;
select pg_temp.test_warmup(false);
select pg_temp.test_warmup(true);
rollback;
